import numpy as np
lines = open('xtbopt.xyz').read().split('\n')
n = int(lines[0])
els=[]; xyz=[]
for l in lines[2:2+n]:
    p=l.split(); els.append(p[0]); xyz.append([float(v) for v in p[1:4]])
xyz=np.array(xyz)
V = [i for i,e in enumerate(els) if e=='V'][0]
for i,e in enumerate(els):
    if e in ('S','N'):
        d = np.linalg.norm(xyz[i]-xyz[V])
        print(i, e, round(d,3))
# also check V...C distances
for i,e in enumerate(els):
    if e=='C':
        d = np.linalg.norm(xyz[i]-xyz[V])
        if d < 3.2: print('C',i,round(d,3))
EOF
